# 简易记账本：字典 + while 菜单
ledger = {}

while True:
    print("\n=== 记账本 ===")
    print("1 记一笔  2 看账本  3 算总账  q 退出")
    cmd = input("请选择：")
    if cmd == "q":
        break
    elif cmd == "1":
        item = input("买了什么：")
        money = int(input("花了多少钱："))
        if item in ledger:                # 同一样东西累加
            ledger[item] = ledger[item] + money
        else:
            ledger[item] = money
        print("记好了！")
    elif cmd == "2":
        for item in ledger:
            print(item, ledger[item], "元")
    elif cmd == "3":
        total = 0
        for item in ledger:
            total = total + ledger[item]
        print("总花费：", total, "元")

print("拜拜，记得省钱！")

