# 简易通讯录：字典的增删查
contacts = {}

while True:
    print("\n=== 通讯录 ===")
    print("1 添加  2 查找  3 删除  4 全部  q 退出")
    cmd = input("请选择：")
    if cmd == "q":
        break
    elif cmd == "1":
        name = input("名字：")
        phone = input("电话：")
        contacts[name] = phone           # 增：直接赋值
        print("已保存")
    elif cmd == "2":
        name = input("找谁：")
        if name in contacts:             # 查：先判断在不在
            print(name, "的电话是", contacts[name])
        else:
            print("没找到这个人")
    elif cmd == "3":
        name = input("删谁：")
        if name in contacts:
            del contacts[name]           # 删：del 关键字
            print("已删除")
    elif cmd == "4":
        for name in contacts:
            print(name, contacts[name])

print("再见！")
